#!/usr/bin/env python3
"""Verify the two lifts of quartic reflection and their elliptic homology actions."""
from hashlib import sha256
from pathlib import Path
import json
import sympy as s
R=Path(__file__).resolve().parents[3];P=R/'research/voevodsky/the_quartic_reflection_is_not_the_elliptic_deck_involution.md';AUTO=R/'research/voevodsky/results/quartic_automorphism_obstruction.json';GEIS=R/'research/voevodsky/results/geiser_mod_two_action.json';TORS=R/'research/voevodsky/results/del_pezzo_complement_torsion.json';OUT=R/'research/voevodsky/results/quartic_reflection_elliptic_action.json';t,w,x,y,E=s.symbols('t w x y E',nonzero=True);F=x**2*t**4-(x**2+y**2-(E-x-y)**2)*t**2+y**2;even=s.expand(F.subs(t,-t)-F)==0;# Riemann-Hurwitz: 2g-2=degree*(2gq-2)+ramification, g=1, degree=2
gplus=s.solve(s.Eq(0,2*(2*s.Symbol('g')-2)+4),s.Symbol('g'))[0];gminus=s.solve(s.Eq(0,2*(2*s.Symbol('g')-2)),s.Symbol('g'))[0];auto=json.loads(AUTO.read_text());geis=json.loads(GEIS.read_text());tors=json.loads(TORS.read_text());text=P.read_text();checks={'quartic_even':even,'lifts_distinct_from_deck':'Neither lift equals \\(j\\)' in text,'rplus_fixed_count_four':2+2==4,'rplus_quotient_genus_zero':gplus==0,'rplus_H1_minus_identity':'r_+^*=-I' in text,'rminus_no_fixed_generic':'has no fixed points on a regular generic curve' in text,'rminus_quotient_genus_one':gminus==1,'rminus_H1_identity':'r_-^*=I' in text,'both_mod2_identity':'Both actions reduce to the identity modulo two' in text,'prior_node_exchange':auto['checks']['even_involution'],'prior_geiser_mod2_identity':geis['disposition']['Geiser_on_E7_mod2']=='identity','remaining_nonzero_classes':tors['disposition']['remaining_parities']==[[1,0],[0,1],[1,1]],'surface_lift_missing':'requires a global branch-curve equation' in text};checks={k:bool(v) for k,v in checks.items()};result={'schema':'marici.voevodsky.quartic-reflection-elliptic-action.v1','packet_sha256':sha256(P.read_bytes()).hexdigest(),'automorphism_sha256':sha256(AUTO.read_bytes()).hexdigest(),'geiser_sha256':sha256(GEIS.read_bytes()).hexdigest(),'lifts':{'r_plus':{'fixed_points':4,'quotient_genus':int(gplus),'H1_action':'-I','mod2':'I'},'r_minus':{'fixed_points':0,'quotient_genus':int(gminus),'H1_action':'I','mod2':'I'}},'checks':checks,'passed':all(checks.values()),'disposition':{'elliptic_mod2_selector':'fails for both lifts','algebraic_kernel_action':'undefined without surface lift','required_input':'global branch-curve equation or explicit rank-nine Picard matrix'}};OUT.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'passed':result['passed'],'checks':checks,'disposition':result['disposition']}));raise SystemExit(0 if result['passed'] else 1)
